{"ok":true,"filePath":"D:\work\ai-agent-v2\src\tool\registry.ts","startLine":1,"endLine":410,"content":"1 | import { BaseTool, ToolOutput } from "./base";
2 | 
3 | /**
4 |  * 工具注册表类
5 |  *
6 |  * 单例模式，管理所有可用的工具
7 |  */
8 | export class ToolRegistry {
9 |     /** 已注册的工具映射 */
10 |     private static tools: Map<string, BaseTool<any>> = new Map();
11 |     private static context: { sessionId?: string; sessionPath?: string; allowedTools?: string[] } = {};
12 | 
13 |     /** 私有构造函数，防止外部实例化 */
14 |     private constructor() {}
15 | 
16 |     /**
17 |      * 注册工具
18 |      *
19 |      * 支持单个工具或工具数组
20 |      *
21 |      * @param tool - 工具实例或工具数组
22 |      * @throws 如果工具名称已存在
23 |      *
24 |      * @example
25 |      * ```ts
26 |      * // 注册单个工具
27 |      * ToolRegistry.register(new BashTool());
28 |      *
29 |      * // 批量注册工具
30 |      * ToolRegistry.register([new BashTool(), new GrepTool()]);
31 |      * ```
32 |      */
33 |     static register<T extends BaseTool<any>>(tool: T | T[]): void {
34 |         const tools = Array.isArray(tool) ? tool : [tool];
35 |         for (const t of tools) {
36 |             if (this.tools.has(t.name)) {
37 |                 throw new Error(`Tool "${t.name}" is already registered`);
38 |             }
39 |             this.tools.set(t.name, t);
40 |         }
41 |     }
42 | 
43 |     /**
44 |      * 注销工具
45 |      *
46 |      * @param name - 工具名称
47 |      * @returns 是否成功注销
48 |      */
49 |     static unregister(name: string): boolean {
50 |         return this.tools.delete(name);
51 |     }
52 | 
53 |     /**
54 |      * 根据名称获取工具
55 |      *
56 |      * @param name - 工具名称
57 |      * @returns 工具实例，如果不存在则返回 undefined
58 |      */
59 |     static get<T extends BaseTool<any> = BaseTool<any>>(name: string): T | undefined {
60 |         return this.tools.get(name) as T | undefined;
61 |     }
62 | 
63 |     /**
64 |      * 获取所有已注册的工具
65 |      *
66 |      * @returns 工具实例数组
67 |      */
68 |     static getAll(): BaseTool<any>[] {
69 |         return Array.from(this.tools.values());
70 |     }
71 | 
72 |     /**
73 |      * 获取所有工具的名称
74 |      *
75 |      * @returns 工具名称数组
76 |      */
77 |     static getNames(): string[] {
78 |         return Array.from(this.tools.keys());
79 |     }
80 | 
81 |     /**
82 |      * 检查工具是否已注册
83 |      *
84 |      * @param name - 工具名称
85 |      * @returns 是否已注册
86 |      */
87 |     static has(name: string): boolean {
88 |         return this.tools.has(name);
89 |     }
90 | 
91 |     /**
92 |      * 获取已注册工具的数量
93 |      *
94 |      * @returns 工具数量
95 |      */
96 |     static get size(): number {
97 |         return this.tools.size;
98 |     }
99 | 
100 |     /**
101 |      * 清空所有已注册的工具
102 |      *
103 |      * @warning 这通常只在测试中使用
104 |      */
105 |     static clear(): void {
106 |         this.tools.clear();
107 |     }
108 | 
109 |     static setContext(context: { sessionId?: string; sessionPath?: string; allowedTools?: string[] }): void {
110 |         const next = { ...this.context, ...context };
111 |         if ('allowedTools' in context && context.allowedTools === undefined) {
112 |             delete (next as any).allowedTools;
113 |         }
114 |         this.context = next;
115 |     }
116 | 
117 |     static getContext(): { sessionId?: string; sessionPath?: string; allowedTools?: string[] } {
118 |         return this.context;
119 |     }
120 | 
121 |     /**
122 |      * 执行指定工具
123 |      *
124 |      * @param name - 工具名称
125 |      * @param args - 工具参数
126 |      * @returns 执行结果
127 |      * @throws 如果工具不存在或参数无效
128 |      */
129 |     static async execute(name: string, args: string): Promise<ToolOutput> {
130 |         const tool = this.get(name);
131 | 
132 |         if (!tool) {
133 |            return `Tool "${name}" not found`;
134 |         }
135 | 
136 |         const allowed = this.context.allowedTools;
137 |         if (allowed && !allowed.includes(name)) {
138 |            return `Tool "${name}" is not allowed in this context`;
139 |         }
140 |         
141 |         
142 |         
143 |        
144 |         const argsObj = JSON.parse(args);
145 |         
146 |         // 验证参数
147 |         const parsed = tool.schema.safeParse(argsObj);
148 |        
149 |         if (!parsed.success) {
150 |            return `Invalid arguments  ${parsed.error.errors.map((e: { message: string }) => e.message).join(', ')}`;
151 |         }
152 |         
153 |        return await tool.execute(parsed.data);
154 |     }
155 | 
156 | 
157 |     /**
158 |      * 获取工具的 schema（用于 LLM 函数调用）
159 |      *
160 |      * 返回符合 OpenAI function calling 格式：
161 |      * https://platform.openai.com/docs/guides/function-calling
162 |      *
163 |      * @returns 所有工具的 schema 数组
164 |      */
165 |     static getSchemas(): Array<{
166 |         type: 'function';
167 |         function: {
168 |             name: string;
169 |             description: string;
170 |             strict?: boolean;
171 |             parameters: Record<string, unknown>;
172 |         };
173 |     }> {
174 |         return this.getAll().map(tool => {
175 |             // 将 zod schema 转换为 JSON Schema 格式
176 |             const zodSchema = tool.schema;
177 |             const jsonSchema = this.zodToJsonSchema(zodSchema);
178 | 
179 |             return {
180 |                 type: 'function',
181 |                 function: {
182 |                     name: tool.name,
183 |                     description: tool.description,
184 |                     strict: true,
185 |                     parameters: jsonSchema,
186 |                 },
187 |             };
188 |         });
189 |     }
190 | 
191 |     /**
192 |      * 将 Zod schema 转换为 JSON Schema 格式
193 |      *
194 |      * @param schema - Zod schema
195 |      * @returns JSON Schema 对象
196 |      */
197 |     private static zodToJsonSchema(schema: any): Record<string, unknown> {
198 |         // 基础实现，处理常见类型
199 |         if (schema._def?.typeName === 'ZodObject') {
200 |             const shape = schema._def.shape();
201 |             const properties: Record<string, unknown> = {};
202 |             const required: string[] = [];
203 | 
204 |             for (const [key, value] of Object.entries(shape)) {
205 |                 const def = (value as any)._def;
206 |                 properties[key] = this.zodTypeToJsonSchema(def, key);
207 | 
208 |                 // 检查是否是可选字段
209 |                 const isOptional = (value as any)._def?.typeName === 'ZodOptional' ||
210 |                                    (value as any).isOptional?.();
211 |                 if (!isOptional) {
212 |                     required.push(key);
213 |                 }
214 |             }
215 | 
216 |             return {
217 |                 type: 'object',
218 |                 properties,
219 |                 required: required.length > 0 ? required : undefined,
220 |                 additionalProperties: false,
221 |             };
222 |         }
223 | 
224 |         return { type: 'object', properties: {}, additionalProperties: false };
225 |     }
226 | 
227 |     /**
228 |      * 将 Zod 类型转换为 JSON Schema 类型
229 |      *
230 |      * @param def - Zod 类型定义
231 |      * @param key - 字段名（用于错误信息）
232 |      * @returns JSON Schema 类型定义
233 |      */
234 |     private static zodTypeToJsonSchema(def: any, key?: string): Record<string, unknown> {
235 |         const typeName = def?.typeName;
236 | 
237 |         switch (typeName) {
238 |             case 'ZodString':
239 |                 return { type: 'string' };
240 | 
241 |             case 'ZodNumber':
242 |                 return { type: 'number' };
243 | 
244 |             case 'ZodBoolean':
245 |                 return { type: 'boolean' };
246 | 
247 |             case 'ZodNull':
248 |                 return { type: 'null' };
249 | 
250 |             case 'ZodArray':
251 |                 const itemType = this.zodTypeToJsonSchema(def.type?._def || def.type, key);
252 |                 return {
253 |                     type: 'array',
254 |                     items: itemType,
255 |                 };
256 | 
257 |             case 'ZodObject':
258 |                 return this.zodToJsonSchema({ _def: def });
259 | 
260 |             case 'ZodOptional':
261 |             case 'ZodNullable':
262 |             case 'ZodDefault':
263 |                 // innerType 是 Zod 对象，需要获取其 _def
264 |                 const wrappedType = def.innerType || def.schema || def.type;
265 |                 if (!wrappedType) {
266 |                     console.warn(`Missing wrapped type for field: ${key}, def:`, def);
267 |                     return {};
268 |                 }
269 |                 return this.zodTypeToJsonSchema(wrappedType._def || wrappedType, key);
270 | 
271 |             case 'ZodEnum':
272 |                 return {
273 |                     type: 'string',
274 |                     enum: def.values,
275 |                 };
276 | 
277 |             case 'ZodLiteral':
278 |                 return {
279 |                     type: typeof def.value,
280 |                     const: def.value,
281 |                 };
282 | 
283 |             case 'ZodUnion':
284 |             case 'ZodDiscriminatedUnion':
285 |                 // 使用 oneOf 替代 anyOf，LLM 理解更好
286 |                 const options = def.options?.map((opt: any) => this.zodTypeToJsonSchema(opt._def || opt));
287 |                 const result: Record<string, unknown> = { oneOf: options };
288 | 
289 |                 // 为 discriminated union 添加示例，帮助 LLM 理解
290 |                 if (def.discriminator && options?.length > 0) {
291 |                     const examples: unknown[] = [];
292 |                     for (const opt of options) {
293 |                         if (opt && typeof opt === 'object' && 'properties' in opt) {
294 |                             const example: Record<string, unknown> = {};
295 |                             const props = opt.properties as Record<string, unknown>;
296 |                             const required = (opt as any).required as string[] || [];
297 | 
298 |                             // 为必需字段生成示例
299 |                             for (const key of required) {
300 |                                 example[key] = this.generateExampleValue(props[key], key);
301 |                             }
302 |                             // 也为一些重要的可选字段生成示例
303 |                             for (const [key, schema] of Object.entries(props)) {
304 |                                 if (!(key in example) && ['content', 'status', 'priority'].includes(key)) {
305 |                                     example[key] = this.generateExampleValue(schema, key);
306 |                                 }
307 |                             }
308 | 
309 |                             if (Object.keys(example).length > 0) {
310 |                                 examples.push(example);
311 |                             }
312 |                         }
313 |                     }
314 |                     if (examples.length > 0) {
315 |                         result.examples = examples;
316 |                     }
317 |                 }
318 |                 return result;
319 | 
320 |             case 'ZodEffects':
321 |                 // 处理带描述的字段
322 |                 const effectType = def.innerType || def.schema || def.type;
323 |                 if (!effectType) {
324 |                     console.warn(`Missing effect inner type for field: ${key}, def:`, def);
325 |                     return {};
326 |                 }
327 |                 const innerSchema = this.zodTypeToJsonSchema(effectType._def || effectType, key);
328 |                 if (def.description) {
329 |                     return { ...innerSchema, description: def.description };
330 |                 }
331 |                 return innerSchema;
332 | 
333 |             default:
334 |                 // 未知类型，使用 any
335 |                 if (typeName !== undefined) {
336 |                     console.warn(`Unknown Zod type: ${typeName} for field: ${key}`);
337 |                 } else {
338 |                     console.warn(`Undefined Zod type definition for field: ${key}, def:`, def);
339 |                 }
340 |                 return {};
341 |         }
342 |     }
343 | 
344 |     /**
345 |      * 从 JSON Schema 生成示例值
346 |      */
347 |     private static generateExampleValue(schema: unknown, key: string): unknown {
348 |         if (!schema || typeof schema !== 'object') {
349 |             return null;
350 |         }
351 | 
352 |         const s = schema as Record<string, unknown>;
353 | 
354 |         // 如果有 const 值，直接使用
355 |         if ('const' in s) {
356 |             return s.const;
357 |         }
358 | 
359 |         // 如果有示例值，直接使用
360 |         if ('example' in s) {
361 |             return s.example;
362 |         }
363 | 
364 |         // 如果是 enum，使用第一个值
365 |         if ('enum' in s && Array.isArray(s.enum) && s.enum.length > 0) {
366 |             return s.enum[0];
367 |         }
368 | 
369 |         // 根据类型生成示例
370 |         if ('type' in s) {
371 |             switch (s.type) {
372 |                 case 'string':
373 |                     // 根据字段名生成更合理的示例
374 |                     if (key === 'content') return 'Complete task documentation';
375 |                     if (key === 'status') return 'pending';
376 |                     if (key === 'priority') return 'medium';
377 |                     if (key === 'id') return 't_1';
378 |                     if (key === 'op') return 'add';
379 |                     return `example_${key}`;
380 |                 case 'number':
381 |                     return 1;
382 |                 case 'boolean':
383 |                     return true;
384 |                 case 'array':
385 |                     return [];
386 |                 case 'object':
387 |                     // 递归生成嵌套对象的示例
388 |                     if ('properties' in s && s.properties && typeof s.properties === 'object' && !Array.isArray(s.properties)) {
389 |                         const nestedExample: Record<string, unknown> = {};
390 |                         const required = (s.required || []) as string[];
391 |                         for (const [k, v] of Object.entries(s.properties)) {
392 |                             // 只为必需字段或常见字段生成示例
393 |                             if (required.includes(k) || ['content', 'status', 'priority'].includes(k)) {
394 |                                 nestedExample[k] = this.generateExampleValue(v, k);
395 |                             }
396 |                         }
397 |                         return nestedExample;
398 |                     }
399 |                     return {};
400 |                 default:
401 |                     return null;
402 |             }
403 |         }
404 | 
405 |         return null;
406 |     }
407 | 
408 | 
409 | }
