{"ok":true,"filePath":"D:\work\ai-agent-v2\src\mcp\manager.ts","startLine":1,"endLine":267,"content":"1 | /**
2 |  * MCP 管理器
3 |  *
4 |  * 管理多个 MCP 服务器连接
5 |  * 负责启动、停止和协调所有 MCP 服务器
6 |  */
7 | 
8 | import { McpClient } from './client';
9 | import { createToolAdapters } from './tool-adapter';
10 | import { ToolRegistry } from '../tool/index';
11 | import { loadMcpConfig } from './config-loader';
12 | import type { McpServerConfig,  McpConnectionInfo } from './types';
13 | import { ConnectionState } from './types';
14 | 
15 | // =============================================================================
16 | // MCP 管理器
17 | // =============================================================================
18 | 
19 | /**
20 |  * MCP 管理器
21 |  *
22 |  * 单例模式，负责管理所有 MCP 服务器连接
23 |  */
24 | export class McpManager {
25 |   /** 单例实例 */
26 |   private static instance: McpManager | null = null;
27 | 
28 |   /** 所有活跃的客户端 */
29 |   private clients = new Map<string, McpClient>();
30 | 
31 |   /** 连接信息 */
32 |   private connectionInfo = new Map<string, McpConnectionInfo>();
33 | 
34 |   /** 私有构造函数 */
35 |   private constructor() {}
36 | 
37 |   /**
38 |    * 获取单例实例
39 |    */
40 |   static getInstance(): McpManager {
41 |     if (!McpManager.instance) {
42 |       McpManager.instance = new McpManager();
43 |     }
44 |     return McpManager.instance;
45 |   }
46 | 
47 |   // -------------------------------------------------------------------------
48 |   // 连接管理
49 |   // -------------------------------------------------------------------------
50 | 
51 |   /**
52 |    * 从配置文件加载并连接所有启用的 MCP 服务器
53 |    */
54 |   async loadAndConnect(configPath?: string): Promise<void> {
55 |     const config = await loadMcpConfig(configPath);
56 | 
57 |     for (const serverConfig of config.mcpServers) {
58 |       if (serverConfig.enabled !== false) {
59 |         await this.connectServer(serverConfig);
60 |       }
61 |     }
62 |   }
63 | 
64 |   /**
65 |    * 连接到单个 MCP 服务器
66 |    */
67 |   async connectServer(config: McpServerConfig): Promise<void> {
68 |     if (this.clients.has(config.name)) {
69 |       throw new Error(`Server "${config.name}" is already connected`);
70 |     }
71 | 
72 |     try {
73 |       const client = new McpClient(config);
74 | 
75 |       // 监听连接状态变化
76 |       client.on('stateChanged', ({ newState }) => {
77 |         this.updateConnectionInfo(config.name, client, newState);
78 |       });
79 | 
80 |       // 监听工具列表变更
81 |       client.on('toolsChanged', async () => {
82 |         await this.refreshServerTools(config.name);
83 |       });
84 | 
85 |       // 监听错误
86 |       client.on('error', (error) => {
87 |         console.error(`[MCP:${config.name}] Error:`, error.message);
88 |       });
89 | 
90 |       // 连接到服务器
91 |       await client.connect();
92 | 
93 |       // 获取工具列表
94 |       const toolsResponse = await client.listTools();
95 | 
96 |       // 存储客户端
97 |       this.clients.set(config.name, client);
98 | 
99 |       // 创建工具适配器并注册
100 |       const adapters = createToolAdapters(client, toolsResponse.tools, config.name);
101 |       ToolRegistry.register(adapters);
102 | 
103 |       // 更新连接信息
104 |       this.updateConnectionInfo(config.name, client, ConnectionState.Connected);
105 | 
106 |       console.log(`[MCP] Connected to "${config.name}" with ${toolsResponse.tools.length} tools`);
107 |     } catch (error) {
108 |       const errorMessage = error instanceof Error ? error.message : 'Unknown error';
109 |       this.connectionInfo.set(config.name, {
110 |         serverName: config.name,
111 |         state: ConnectionState.Error,
112 |         tools: [],
113 |         error: errorMessage,
114 |       });
115 |       throw error;
116 |     }
117 |   }
118 | 
119 |   /**
120 |    * 断开指定服务器连接
121 |    */
122 |   async disconnectServer(serverName: string): Promise<void> {
123 |     const client = this.clients.get(serverName);
124 |     if (!client) {
125 |       return;
126 |     }
127 | 
128 |     // 注销该服务器的所有工具
129 |     const tools = client.getTools();
130 |     for (const tool of tools) {
131 |       const toolName = `${serverName}/${tool.name}`;
132 |       ToolRegistry.unregister(toolName);
133 |     }
134 | 
135 |     // 断开连接
136 |     await client.disconnect();
137 | 
138 |     // 移除客户端
139 |     this.clients.delete(serverName);
140 |     this.connectionInfo.delete(serverName);
141 | 
142 |     console.log(`[MCP] Disconnected from "${serverName}"`);
143 |   }
144 | 
145 |   /**
146 |    * 断开所有连接
147 |    */
148 |   async disconnectAll(): Promise<void> {
149 |     const serverNames = Array.from(this.clients.keys());
150 |     await Promise.all(serverNames.map(name => this.disconnectServer(name)));
151 |   }
152 | 
153 |   // -------------------------------------------------------------------------
154 |   // 工具管理
155 |   // -------------------------------------------------------------------------
156 | 
157 |   /**
158 |    * 刷新指定服务器的工具列表
159 |    */
160 |   private async refreshServerTools(serverName: string): Promise<void> {
161 |     const client = this.clients.get(serverName);
162 |     if (!client) {
163 |       return;
164 |     }
165 | 
166 |     // 先注销旧工具
167 |     const oldTools = client.getTools();
168 |     for (const tool of oldTools) {
169 |       const toolName = `${serverName}/${tool.name}`;
170 |       ToolRegistry.unregister(toolName);
171 |     }
172 | 
173 |     // 获取新工具列表
174 |     const toolsResponse = await client.listTools();
175 | 
176 |     // 创建并注册新工具
177 |     const adapters = createToolAdapters(client, toolsResponse.tools, serverName);
178 |     ToolRegistry.register(adapters);
179 | 
180 |     // 更新连接信息
181 |     this.updateConnectionInfo(serverName, client, ConnectionState.Connected);
182 | 
183 |     console.log(`[MCP] Refreshed ${toolsResponse.tools.length} tools from "${serverName}"`);
184 |   }
185 | 
186 |   // -------------------------------------------------------------------------
187 |   // 状态和信息
188 |   // -------------------------------------------------------------------------
189 | 
190 |   /**
191 |    * 获取所有连接信息
192 |    */
193 |   getConnectionInfo(): McpConnectionInfo[] {
194 |     return Array.from(this.connectionInfo.values());
195 |   }
196 | 
197 |   /**
198 |    * 获取指定服务器的连接信息
199 |    */
200 |   getServerInfo(serverName: string): McpConnectionInfo | undefined {
201 |     return this.connectionInfo.get(serverName);
202 |   }
203 | 
204 |   /**
205 |    * 获取所有已连接的服务器名称
206 |    */
207 |   getConnectedServers(): string[] {
208 |     return Array.from(this.clients.keys()).filter(name => {
209 |       const client = this.clients.get(name);
210 |       return client?.state === ConnectionState.Connected;
211 |     });
212 |   }
213 | 
214 |   /**
215 |    * 获取所有 MCP 工具数量
216 |    */
217 |   getTotalToolsCount(): number {
218 |     let count = 0;
219 |     for (const info of this.connectionInfo.values()) {
220 |       count += info.tools.length;
221 |     }
222 |     return count;
223 |   }
224 | 
225 |   // -------------------------------------------------------------------------
226 |   // 私有方法
227 |   // -------------------------------------------------------------------------
228 | 
229 |   /**
230 |    * 更新连接信息
231 |    */
232 |   private updateConnectionInfo(
233 |     serverName: string,
234 |     client: McpClient,
235 |     state: ConnectionState
236 |   ): void {
237 |     this.connectionInfo.set(serverName, {
238 |       serverName,
239 |       state,
240 |       tools: client.getTools(),
241 |     });
242 |   }
243 | }
244 | 
245 | // =============================================================================
246 | // 便捷函数
247 | // =============================================================================
248 | 
249 | /**
250 |  * 初始化 MCP 管理器并加载所有配置的服务器
251 |  *
252 |  * @param configPath - 配置文件路径（可选）
253 |  * @returns MCP 管理器实例
254 |  */
255 | export async function initializeMcp(configPath?: string): Promise<McpManager> {
256 |   const manager = McpManager.getInstance();
257 |   await manager.loadAndConnect(configPath);
258 |   return manager;
259 | }
260 | 
261 | /**
262 |  * 获取 MCP 管理器实例
263 |  */
264 | export function getMcpManager(): McpManager {
265 |   return McpManager.getInstance();
266 | }
