{"ok":true,"filePath":"D:\work\ai-agent-v2\src\mcp\tool-adapter.ts","startLine":1,"endLine":160,"content":"1 | /**
2 |  * MCP 工具适配器
3 |  *
4 |  * 将 MCP 工具适配到 BaseTool 接口
5 |  */
6 | 
7 | import { z } from 'zod';
8 | import { BaseTool } from '../tool/base';
9 | import type { McpClient, Tool as McpTool } from './client';
10 | import { ToolCallResponse } from './types';
11 | import { jsonSchemaToZod } from './json-schema-to-zod';
12 | 
13 | // =============================================================================
14 | // MCP 工具适配器
15 | // =============================================================================
16 | 
17 | /**
18 |  * MCP 工具适配器
19 |  *
20 |  * 将 MCP 服务器暴露的工具适配为 BaseTool 接口
21 |  */
22 | export class McpToolAdapter extends BaseTool<z.ZodType<any>> {
23 |   /** MCP 客户端 */
24 |   private client: McpClient;
25 | 
26 |   /** MCP 工具定义 */
27 |   private toolDefinition: McpTool;
28 | 
29 |   /** 服务器名称前缀 */
30 |   private serverName: string;
31 | 
32 |   /** 符合 OpenAI API 要求的工具名称 */
33 |   private _sanitizedName: string;
34 | 
35 |   /**
36 |    * 构造函数
37 |    */
38 |   constructor(client: McpClient, toolDefinition: McpTool, serverName: string) {
39 |     super();
40 | 
41 |     this.client = client;
42 |     this.toolDefinition = toolDefinition;
43 |     this.serverName = serverName;
44 | 
45 |     // 将 JSON Schema 转换为 Zod schema
46 |     this.schema = jsonSchemaToZod(toolDefinition.inputSchema);
47 | 
48 |     // 生成符合 OpenAI API 要求的工具名称（只包含字母、数字、下划线、连字符）
49 |     this._sanitizedName = this.sanitizeName(`${serverName}_${toolDefinition.name}`);
50 |   }
51 | 
52 |   // -------------------------------------------------------------------------
53 |   // BaseTool 实现
54 |   // -------------------------------------------------------------------------
55 | 
56 |   /**
57 |    * 工具名称（带服务器前缀以避免冲突）
58 |    * 使用下划线代替斜杠，符合 OpenAI API 要求
59 |    */
60 |   get name(): string {
61 |     return this._sanitizedName;
62 |   }
63 | 
64 |   /**
65 |    * 清理工具名称，使其符合 OpenAI API 要求
66 |    * 只允许字母、数字、下划线和连字符
67 |    */
68 |   private sanitizeName(name: string): string {
69 |     return name
70 |       .replace(/[^a-zA-Z0-9_-]/g, '_')  // 替换非法字符为下划线
71 |       .replace(/-+/g, '_')              // 将连字符替换为下划线
72 |       .replace(/^_+|_+$/g, '');         // 移除开头和结尾的下划线
73 |   }
74 | 
75 |   /**
76 |    * 工具描述
77 |    */
78 |   get description(): string {
79 |     const baseDesc = this.toolDefinition.description || this.toolDefinition.name;
80 |     return `[MCP:${this.serverName}] ${baseDesc}`;
81 |   }
82 | 
83 |   /**
84 |    * 参数 schema
85 |    */
86 |   declare schema: z.ZodType<any>;
87 | 
88 |   /**
89 |    * 执行工具
90 |    */
91 |   async execute(args: z.infer<typeof this.schema>): Promise<string> {
92 |     try {
93 |       const response = await this.client.callTool({
94 |         name: this.toolDefinition.name,
95 |         arguments: args,
96 |       });
97 | 
98 |       return this.formatToolResponse(response);
99 |     } catch (error) {
100 |       if (error instanceof Error) {
101 |         return `Error executing tool: ${error.message}`;
102 |       }
103 |       return 'Error executing tool: Unknown error';
104 |     }
105 |   }
106 | 
107 |   // -------------------------------------------------------------------------
108 |   // 私有方法
109 |   // -------------------------------------------------------------------------
110 | 
111 |   /**
112 |    * 格式化工具响应
113 |    */
114 |   private formatToolResponse(response: ToolCallResponse): string {
115 |     if (response.isError) {
116 |       return `Tool execution error: ${this.extractTextContent(response)}`;
117 |     }
118 | 
119 |     // 如果有结构化内容，优先返回
120 |     if (response.structuredContent) {
121 |       return JSON.stringify(response.structuredContent, null, 2);
122 |     }
123 | 
124 |     // 否则返回文本内容
125 |     return this.extractTextContent(response);
126 |   }
127 | 
128 |   /**
129 |    * 提取文本内容
130 |    */
131 |   private extractTextContent(response: ToolCallResponse): string {
132 |     const textContents = response.content
133 |       .filter((item: any) => item.type === 'text')
134 |       .map((item: any) => item.text)
135 |       .join('\n');
136 | 
137 |     return textContents || 'No text content in response';
138 |   }
139 | }
