{"ok":true,"filePath":"D:\work\ai-agent-v2\src\skills\loader.ts","startLine":1,"endLine":266,"content":"1 | /**
2 |  * Skill Loader
3 |  *
4 |  * 负责发现、加载和管理技能
5 |  * 兼容 Claude Code Skills 格式
6 |  */
7 | 
8 | import * as fs from 'fs/promises';
9 | import { watch } from 'fs';
10 | import * as path from 'path';
11 | import fg from 'fast-glob';
12 | import matter from 'gray-matter';
13 | import type {
14 |     Skill,
15 |     SkillFile,
16 |     SkillLoaderOptions,
17 |     SkillMetadata,
18 |     SkillFrontmatter
19 | } from './types';
20 | 
21 | /**
22 |  * 默认技能目录
23 |  */
24 | const DEFAULT_SKILLS_DIR = path.join(process.cwd(), 'skills');
25 | 
26 | /**
27 |  * 技能加载器类
28 |  */
29 | export class SkillLoader {
30 |     /** 已加载的技能映射 */
31 |     private skills: Map<string, Skill> = new Map();
32 | 
33 |     /** 技能目录 */
34 |     private skillsDir: string;
35 | 
36 |     /** 是否启用热重载 */
37 |     private hotReload: boolean;
38 | 
39 |     /** 文件监听器（用于热重载） */
40 |     private watcher: ReturnType<typeof watch> | null = null;
41 | 
42 |     constructor(options: SkillLoaderOptions = {}) {
43 |         this.skillsDir = options.skillsDir || DEFAULT_SKILLS_DIR;
44 |         this.hotReload = options.hotReload || false;
45 |     }
46 | 
47 |     /**
48 |      * 发现并加载所有技能
49 |      */
50 |     async load(): Promise<void> {
51 |         try {
52 |             // 查找所有 SKILL.md 文件
53 |             const skillFiles = await fg('**/SKILL.md', {
54 |                 cwd: this.skillsDir,
55 |                 absolute: true,
56 |                 onlyFiles: true,
57 |             });
58 | 
59 |             // 加载每个技能
60 |             for (const skillPath of skillFiles) {
61 |                 await this.loadSkill(skillPath);
62 |             }
63 | 
64 |             // 启用热重载（如果配置）
65 |             if (this.hotReload) {
66 |                 this.enableHotReload();
67 |             }
68 |         } catch (error) {
69 |             // 技能目录不存在是可接受的
70 |             if ((error as NodeJS.ErrnoException).code !== 'ENOENT') {
71 |                 console.warn(`[Skills] Failed to load skills: ${(error as Error).message}`);
72 |             }
73 |         }
74 |     }
75 | 
76 |     /**
77 |      * 加载单个技能文件
78 |      */
79 |     async loadSkill(skillPath: string): Promise<void> {
80 |         try {
81 |             const content = await fs.readFile(skillPath, 'utf-8');
82 |             const skillDir = path.dirname(skillPath);
83 |             const relativePath = path.relative(this.skillsDir, skillDir);
84 | 
85 |             const parsed = this.parseSkillMd(content, skillDir);
86 | 
87 |             // 验证技能名称
88 |             if (!this.isValidSkillName(parsed.metadata.name)) {
89 |                 console.warn(`[Skills] Invalid skill name: ${parsed.metadata.name}`);
90 |                 return;
91 |             }
92 | 
93 |             // 验证描述长度
94 |             if (parsed.metadata.description.length > 1024) {
95 |                 console.warn(`[Skills] Description too long for skill: ${parsed.metadata.name}`);
96 |                 return;
97 |             }
98 | 
99 |             const skill: Skill = {
100 |                 metadata: parsed.metadata,
101 |                 // 不在加载时存储完整内容，使用按需加载
102 |             };
103 | 
104 |             this.skills.set(parsed.metadata.name, skill);
105 |         } catch (error) {
106 |             console.warn(`[Skills] Failed to load skill ${skillPath}: ${(error as Error).message}`);
107 |         }
108 |     }
109 | 
110 |     /**
111 |      * 解析 SKILL.md 文件内容
112 |      */
113 |     parseSkillMd(content: string, skillDir: string): SkillFile {
114 |         const parsed = matter(content);
115 |         const frontmatter = parsed.data as SkillFrontmatter;
116 | 
117 |         if (!frontmatter.name || !frontmatter.description) {
118 |             throw new Error('Missing required fields in frontmatter (name, description)');
119 |         }
120 | 
121 |         return {
122 |             metadata: {
123 |                 name: frontmatter.name,
124 |                 description: frontmatter.description,
125 |                 path: skillDir,
126 |             },
127 |             content: parsed.content,
128 |         };
129 |     }
130 | 
131 |     /**
132 |      * 验证技能名称格式
133 |      */
134 |     private isValidSkillName(name: string): boolean {
135 |         if (name.length > 64) return false;
136 |         return /^[a-z0-9-]+$/.test(name);
137 |     }
138 | 
139 |     /**
140 |      * 获取指定技能
141 |      */
142 |     getSkill(name: string): Skill | undefined {
143 |         return this.skills.get(name);
144 |     }
145 | 
146 |     /**
147 |      * 获取所有技能
148 |      */
149 |     getAllSkills(): Skill[] {
150 |         return Array.from(this.skills.values());
151 |     }
152 | 
153 |     /**
154 |      * 获取所有技能元数据（不包含内容）
155 |      */
156 |     getAllMetadata(): SkillMetadata[] {
157 |         return this.getAllSkills().map((skill) => skill.metadata);
158 |     }
159 | 
160 |     /**
161 |      * 获取技能数量
162 |      */
163 |     get size(): number {
164 |         return this.skills.size;
165 |     }
166 | 
167 |     /**
168 |      * 启用热重载（开发模式）
169 |      */
170 |     enableHotReload(): void {
171 |         if (this.watcher) {
172 |             return; // 已经启用
173 |         }
174 | 
175 |         // 使用简单的轮询实现热重载（避免额外依赖）
176 |         let previousFiles = new Set<string>();
177 | 
178 |         const check = async () => {
179 |             try {
180 |                 const skillFiles = await fg('**/SKILL.md', {
181 |                     cwd: this.skillsDir,
182 |                     absolute: true,
183 |                     onlyFiles: true,
184 |                 });
185 | 
186 |                 const currentFiles = new Set(skillFiles);
187 | 
188 |                 // 检测新增或修改的文件
189 |                 for (const file of skillFiles) {
190 |                     if (!previousFiles.has(file)) {
191 |                         await this.loadSkill(file);
192 |                     }
193 |                 }
194 | 
195 |                 // 检测删除的文件
196 |                 for (const file of previousFiles) {
197 |                     if (!currentFiles.has(file)) {
198 |                         const skillDir = path.dirname(file);
199 |                         const relativePath = path.relative(this.skillsDir, skillDir);
200 |                         const skillName = path.basename(relativePath);
201 | 
202 |                         // 尝试通过路径推断技能名称并删除
203 |                         for (const [name, skill] of this.skills.entries()) {
204 |                             if (skill.metadata.path === skillDir) {
205 |                                 this.skills.delete(name);
206 |                                 break;
207 |                             }
208 |                         }
209 |                     }
210 |                 }
211 | 
212 |                 previousFiles = currentFiles;
213 |             } catch (error) {
214 |                 // 静默处理错误
215 |             }
216 |         };
217 | 
218 |         // 每秒检查一次
219 |         setInterval(check, 1000);
220 |     }
221 | 
222 |     /**
223 |      * 读取技能文件内容（按需加载）
224 |      */
225 |     async readSkillFile(skillName: string, fileName: string = 'SKILL.md'): Promise<string> {
226 |         const skill = this.getSkill(skillName);
227 |         if (!skill) {
228 |             throw new Error(`Skill "${skillName}" not found`);
229 |         }
230 | 
231 |         const filePath = path.join(skill.metadata.path, fileName);
232 |         return await fs.readFile(filePath, 'utf-8');
233 |     }
234 | 
235 |     /**
236 |      * 清空所有技能
237 |      */
238 |     clear(): void {
239 |         this.skills.clear();
240 |     }
241 | }
242 | 
243 | /**
244 |  * 全局技能加载器实例
245 |  */
246 | let fgalSkillLoader: SkillLoader | null = null;
247 | 
248 | /**
249 |  * 获取全局技能加载器实例
250 |  */
251 | export function getSkillLoader(options?: SkillLoaderOptions): SkillLoader {
252 |     if (!fgalSkillLoader) {
253 |         fgalSkillLoader = new SkillLoader(options);
254 |     }
255 |     return fgalSkillLoader;
256 | }
257 | 
258 | /**
259 |  * 初始化技能加载器
260 |  */
261 | export async function initializeSkills(options?: SkillLoaderOptions): Promise<SkillLoader> {
262 |     const loader = getSkillLoader(options);
263 |     await loader.load();
264 |     return loader;
265 | }
