{"ok":true,"filePath":"D:\work\ai-agent-v2\src\skills\skill-tool.ts","startLine":1,"endLine":208,"content":"1 | /**
2 |  * ============================================================================
3 |  * 文件名：skill-tool.ts
4 |  * 所属包：src/skills
5 |  * ============================================================================
6 |  *
7 |  * 文件作用：
8 |  * Skill 工具模块。允许 AI 加载技能（预定义的任务指导）。
9 |  *
10 |  * 主要功能：
11 |  * - SkillTool：加载技能的工具
12 |  * - 动态生成工具描述，包含所有可用技能列表
13 |  * - 解析技能文件内容
14 |  *
15 |  * 依赖关系：
16 |  * - zod：类型验证
17 |  * - ../tool/base：工具基类
18 |  * - ./loader：技能加载
19 |  * - ./parser：Markdown 解析
20 |  *
21 |  * 导出内容：
22 |  * - SkillTool：技能工具定义
23 |  * - createSkillTool：创建技能工具的工厂函数
24 |  *
25 |  * 参数：
26 |  * - name：技能标识符（如 "code-review" 或 "category/helper"）
27 |  *
28 |  * 返回：
29 |  * - title：技能名称标题
30 |  * - output：格式化的技能内容
31 |  * - metadata：技能元数据（名称、目录）
32 |  *
33 |  * 工具描述：
34 |  * - 动态生成，包含所有可用技能列表
35 |  * - 使用 XML 格式展示技能信息
36 |  *
37 |  * 使用场景：
38 |  * - AI 需要特定任务的详细指导时
39 |  * - 遵循预定义的工作流程
40 |  * - 获取专业知识
41 |  *
42 |  * @module skills/skill-tool
43 |  */
44 | 
45 | import { z } from 'zod';
46 | import * as path from 'path';
47 | import { BaseTool } from '../tool/base';
48 | import { getSkillLoader } from './loader';
49 | import { parseSkillMarkdown } from './parser';
50 | 
51 | /**
52 |  * 技能工具执行结果
53 |  */
54 | export interface SkillToolResult {
55 |     /** 结果标题 */
56 |     title: string;
57 |     /** 格式化的技能内容 */
58 |     output: string;
59 |     /** 技能元数据 */
60 |     metadata: {
61 |         name: string;
62 |         dir: string;
63 |     };
64 | }
65 | 
66 | /**
67 |  * 参数 Schema
68 |  *
69 |  * 定义加载技能所需的参数。
70 |  */
71 | const parameters = z.object({
72 |     name: z.string().describe("The skill identifier from available_skills (e.g., 'code-review' or 'category/helper')"),
73 | });
74 | 
75 | /**
76 |  * 技能工具类
77 |  *
78 |  * 允许 AI 加载技能以获取特定任务的详细指导。
79 |  */
80 | export class SkillTool extends BaseTool<typeof parameters> {
81 |     name = 'skill';
82 |     description = '';
83 |     schema = parameters;
84 | 
85 |     /**
86 |      * 构造函数
87 |      *
88 |      * @param includeDescription - 是否包含详细描述（包含可用技能列表）
89 |      */
90 |     constructor(private includeDescription: boolean = true) {
91 |         super();
92 |         this.description = this.generateDescription();
93 |     }
94 | 
95 |     /**
96 |      * 生成工具描述
97 |      *
98 |      * 动态生成包含所有可用技能的描述。
99 |      */
100 |     private generateDescription(): string {
101 |         if (!this.includeDescription) {
102 |             return 'Load a skill to get detailed instructions for a specific task.';
103 |         }
104 | 
105 |         const loader = getSkillLoader();
106 |         const skills = loader.getAllMetadata();
107 | 
108 |         if (skills.length === 0) {
109 |             return 'Load a skill to get detailed instructions for a specific task. No skills are currently available.';
110 |         }
111 | 
112 |         const skillsList = skills.flatMap((skill) => [
113 |             '  <skill>',
114 |             `    <name>${skill.name}</name>`,
115 |             `    <description>${skill.description}</description>`,
116 |             '  </skill>',
117 |         ]);
118 | 
119 |         return [
120 |             'Load a skill to get detailed instructions for a specific task.',
121 |             'Skills provide specialized knowledge and step-by-step guidance.',
122 |             'Use this when a task matches an available skill\'s description.',
123 |             '<available_skills>',
124 |             ...skillsList,
125 |             '</available_skills>',
126 |         ].join(' ');
127 |     }
128 | 
129 |     /**
