198 |   // -------------------------------------------------------------------------
199 |   // 消息处理
200 |   // -------------------------------------------------------------------------
201 | 
202 |   /**
203 |    * 发送请求
204 |    */
205 |   private async sendRequest(method: string, params?: Record<string, unknown>): Promise<JsonRpcResponse> {
206 |     return new Promise((resolve, reject) => {
207 |       const id = ++this.requestId;
208 | 
209 |       const request: JsonRpcRequest = {
210 |         jsonrpc: '2.0',
211 |         id,
212 |         method,
213 |         params: params as Record<string, unknown>,
214 |       };
215 | 
216 |       // 设置超时
217 |       const timeout = setTimeout(() => {
218 |         this.pendingRequests.delete(id);
219 |         reject(new Error(`Request timeout: ${method}`));
220 |       }, this.REQUEST_TIMEOUT);
221 | 
222 |       // 存储待处理的请求
223 |       this.pendingRequests.set(id, { resolve, reject, timeout });
224 | 
225 |       // 发送请求
226 |       this.sendMessage(request);
227 |     });
228 |   }
229 | 
230 |   /**
231 |    * 发送消息到服务器
232 |    */
233 |   private sendMessage(message: JsonRpcRequest): void {
234 |     if (!this.process?.stdin) {
235 |       throw new Error('Process not connected');
236 |     }
237 | 
238 |     const data = JSON.stringify(message);
239 |     this.process.stdin.write(data + '\n');
240 |   }
241 | 
242 |   /**
243 |    * 处理接收到的消息
244 |    */
245 |   private handleMessage(data: string): void {
246 |     // MCP 使用 JSON-RPC 2.0，消息可能是多行的
247 |     const lines = data.split('\n').filter(line => line.trim().length > 0);
248 | 
249 |     for (const line of lines) {
250 |       try {
251 |         const message = JSON.parse(line);
252 | 
253 |         // 检查是否是响应
254 |         if ('id' in message) {
255 |           this.handleResponse(message as JsonRpcResponse);
256 |         } else {
257 |           // 通知
258 |           this.handleNotification(message as JsonRpcNotification);
259 |         }
260 |       } catch (error) {
261 |         this.emit('parseError', error);
262 |       }
263 |     }
264 |   }
265 | 
266 |   /**
267 |    * 处理响应
268 |    */
269 |   private handleResponse(response: JsonRpcResponse): void {
270 |     const pending = this.pendingRequests.get(response.id);
271 | 
272 |     if (pending) {
273 |       clearTimeout(pending.timeout);
274 |       this.pendingRequests.delete(response.id);
275 | 
276 |       if (response.error) {
277 |         pending.reject(new Error(`${response.error.code}: ${response.error.message}`));
278 |       } else {
279 |         pending.resolve(response);
280 |       }
281 |     }
282 |   }
283 | 
284 |   /**
285 |    * 处理通知
286 |    */
287 |   private handleNotification(notification: JsonRpcNotification): void {
288 |     // 处理工具列表变更通知
289 |     if (notification.method === 'notifications/tools/list_changed') {
290 |       this.emit('toolsChanged');
291 |     }
292 | 
293 |     this.emit('notification', notification);
294 |   }
295 | 
296 |   /**
297 |    * 拒绝所有待处理的请求
298 |    */
299 |   private rejectAllPendingRequests(error: Error): void {
300 |     for (const [, pending] of this.pendingRequests) {
301 |       clearTimeout(pending.timeout);
302 |       pending.reject(error);
303 |     }
304 |     this.pendingRequests.clear();
305 |   }
306 | 
307 |   // -------------------------------------------------------------------------
308 |   // 状态管理
