{"ok":true,"filePath":"D:\work\ai-agent-v2\src\mcp\config-loader.ts","startLine":1,"endLine":226,"content":"1 | /**
2 |  * MCP Config Loader
3 |  *
4 |  * 加载 MCP 配置文件
5 |  * 支持 .mcp.json 和 mcp.json 格式
6 |  */
7 | 
8 | import { readFile } from 'fs/promises';
9 | import { existsSync } from 'fs';
10 | import { join } from 'path';
11 | import type { McpServerConfig } from './types';
12 | 
13 | // =============================================================================
14 | // MCP 配置文件结构
15 | // =============================================================================
16 | 
17 | /**
18 |  * MCP 配置文件结构
19 |  *
20 |  * 兼容常见的 MCP 配置格式
21 |  */
22 | export interface McpConfigFile {
23 |   /** MCP 服务器列表 */
24 |   mcpServers: McpServerConfig[];
25 | }
26 | 
27 | // =============================================================================
28 | // 配置加载器
29 | // =============================================================================
30 | 
31 | /**
32 |  * 配置文件搜索路径（按优先级排序）
33 |  */
34 | const CONFIG_SEARCH_PATHS = [
35 |   '.mcp.json',
36 |   'mcp.json',
37 |   '.mcp/config.json',
38 |   join('.claude', 'mcp.json'),
39 |   join('.config', 'mcp.json'),
40 | ];
41 | 
42 | /**
43 |  * 加载 MCP 配置文件
44 |  *
45 |  * @param configPath - 配置文件路径（可选，如果不提供则搜索默认路径）
46 |  * @returns MCP 配置
47 |  * @throws 如果找不到配置文件或解析失败
48 |  */
49 | export async function loadMcpConfig(configPath?: string): Promise<McpConfigFile> {
50 |   let filePath: string | undefined;
51 | 
52 |   if (configPath) {
53 |     filePath = configPath;
54 |     if (!existsSync(filePath)) {
55 |       throw new Error(`Config file not found: ${filePath}`);
56 |     }
57 |   } else {
58 |     // 搜索默认配置文件
59 |     filePath = findConfigFile();
60 |     if (!filePath) {
61 |       // 没有找到配置文件，返回空配置
62 |       return { mcpServers: [] };
63 |     }
64 |   }
65 | 
66 |   try {
67 |     const content = await readFile(filePath, 'utf-8');
68 |     const rawConfig = JSON.parse(content);
69 | 
70 |     // 处理不同的配置格式
71 |     return normalizeConfig(rawConfig);
72 |   } catch (error) {
73 |     if (error instanceof SyntaxError) {
74 |       throw new Error(`Failed to parse config file ${filePath}: ${error.message}`);
75 |     }
76 |     throw error;
77 |   }
78 | }
79 | 
80 | /**
81 |  * 查找配置文件
82 |  *
83 |  * @returns 找到的配置文件路径，如果没有找到则返回 null
84 |  */
85 | function findConfigFile(): string | undefined {
86 |   for (const path of CONFIG_SEARCH_PATHS) {
87 |     if (existsSync(path)) {
88 |       return path;
89 |     }
90 |   }
91 |   return undefined;
92 | }
93 | 
94 | /**
95 |  * 标准化配置格式
96 |  *
97 |  * 支持多种配置格式的转换：
98 |  * - Claude Desktop 格式
99 |  * - Cursor 格式
100 |  * - 标准格式
101 |  *
102 |  * @param rawConfig - 原始配置对象
103 |  * @returns 标准化的 MCP 配置
104 |  */
105 | function normalizeConfig(rawConfig: any): McpConfigFile {
106 |   // 检查是否是标准格式
107 |   if ('mcpServers' in rawConfig && Array.isArray(rawConfig.mcpServers)) {
108 |     return {
109 |       mcpServers: rawConfig.mcpServers.map(normalizeServerConfig),
110 |     };
111 |   }
112 | 
113 |   // 检查是否是 Claude Desktop/Cursor 格式 (mcpServers 是对象)
114 |   if ('mcpServers' in rawConfig && typeof rawConfig.mcpServers === 'object') {
115 |     return {
116 |       mcpServers: Object.entries(rawConfig.mcpServers).map(([name, config]) => {
117 |         const serverConfig = config as any;
118 |         return normalizeServerConfig({
119 |           name,
120 |           ...serverConfig,
121 |         });
122 |       }),
123 |     };
124 |   }
125 | 
126 |   // 检查是否是简化格式（直接是服务器配置数组）
127 |   if (Array.isArray(rawConfig)) {
128 |     return {
129 |       mcpServers: rawConfig.map(normalizeServerConfig),
130 |     };
131 |   }
132 | 
133 |   // 未知格式
134 |   console.warn('[MCP] Unknown config format, treating as empty config');
135 |   return { mcpServers: [] };
136 | }
137 | 
138 | /**
139 |  * 标准化服务器配置
140 |  *
141 |  * 支持多种命令格式的转换：
142 |  * - npx 命令: "npx -y @modelcontextprotocol/server-xyz"
143 |  * - 完整命令: { command: "node", args: ["server.js"] }
144 |  *
145 |  * @param config - 服务器配置
146 |  * @returns 标准化的服务器配置
147 |  */
148 | function normalizeServerConfig(config: any): McpServerConfig {
149 |   const normalized: any = {
150 |     name: config.name || `server_${Date.now()}`,
151 |     transport: 'stdio',
152 |     enabled: config.enabled !== false,
153 |   };
154 | 
155 |   // 处理命令格式
156 |   if (typeof config.command === 'string') {
157 |     normalized.command = config.command;
158 |     normalized.args = config.args || [];
159 |   } else if (typeof config.command === 'object') {
160 |     normalized.command = config.command;
161 |   } else if (typeof config === 'string') {
162 |     // 简化的 npx 命令格式
163 |     normalized.command = 'npx';
164 |     normalized.args = ['-y', config];
165 |   }
166 | 
167 |   // 环境变量
168 |   if (config.env) {
169 |     // 处理环境变量中的 ${VAR} 格式
170 |     normalized.env = resolveEnvVars(config.env);
171 |   }
172 | 
173 |   return normalized as McpServerConfig;
174 | }
175 | 
176 | /**
177 |  * 解析环境变量
178 |  *
179 |  * 支持 ${VAR_NAME} 格式的环境变量引用
180 |  *
181 |  * @param env - 环境变量对象
182 |  * @returns 解析后的环境变量
183 |  */
184 | function resolveEnvVars(env: Record<string, string>): Record<string, string> {
185 |   const resolved: Record<string, string> = {};
186 | 
187 |   for (const [key, value] of Object.entries(env)) {
188 |     if (typeof value === 'string') {
189 |       // 匹配 ${VAR_NAME} 格式
190 |       resolved[key] = value.replace(/\$\{([^}]+)\}/g, (_, varName) => {
191 |         return process.env[varName] || '';
192 |       });
193 |     } else {
194 |       resolved[key] = value;
195 |     }
196 |   }
197 | 
198 |   return resolved;
199 | }
200 | 
201 | // =============================================================================
202 | // 环境变量辅助函数
203 | // =============================================================================
204 | 
205 | /**
206 |  * 获取环境变量值
207 |  *
208 |  * 优先使用传入的值，如果为 ${VAR} 格式则从环境变量读取
209 |  *
210 |  * @param value - 值或环境变量引用
211 |  * @returns 解析后的值
212 |  */
213 | export function getEnvValue(value: string): string {
214 |   if (value.startsWith('${') && value.endsWith('}')) {
215 |     const varName = value.slice(2, -1);
216 |     return process.env[varName] || '';
217 |   }
218 |   return value;
219 | }
220 | 
